(async()=>{const d=await(await navigator.gpu.requestAdapter()).requestDevice(),out={};for(const alphaMode of ['opaque','premultiplied']){const c=document.createElement('canvas');c.width=2;c.height=2;const g=c.getContext('webgpu'),read=source=>{const canvas=new OffscreenCanvas(2,2),x=canvas.getContext('2d');x.drawImage(source,0,0);return Array.from(x.getImageData(0,0,1,1).data)};g.configure({device:d,format:'rgba8unorm',alphaMode});const r=out[alphaMode]={before:read(c)};for(const color of [[.2,.1,.05,.5],[.8,.4,.2,.5],[.3,.6,.9,.5]]){const e=d.createCommandEncoder(),p=e.beginRenderPass({colorAttachments:[{view:g.getCurrentTexture().createView(),loadOp:'clear',storeOp:'store',clearValue:color}]});p.end();d.queue.submit([e.finish()]);r[color.join()]=[read(c),read(await createImageBitmap(c))]}g.unconfigure();r.after=read(c);g.configure({device:d,format:'rgba8unorm',alphaMode});r.reconfigured=read(c);const encoder=d.createCommandEncoder(),pass=encoder.beginRenderPass({colorAttachments:[{view:g.getCurrentTexture().createView(),loadOp:'clear',storeOp:'store',clearValue:[.1,.2,.3,.5]}]});pass.end();d.queue.submit([encoder.finish()]);g.unconfigure();r.noPriorRead=read(c)}d.destroy();return out})()